115	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
116	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
117	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
118	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
119	     * nothing. Level {@code 4} is reserved for tenure.
120	     */
121	    default Integer formatMembershipLevel(Owner owner) {
122	        if (owner == null) {
123	            return null;
124	        }
125	        int level = 1;
126	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
127	        if (hasEmail) {
128	            level++;
129	        }
130	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
131	        if (uniqueName) {
132	            level++;
133	        }
134	        return Math.min(level, 3);
135	    }
